const state={category:'all',search:'',cart:readJSON('amarCart',[]),orders:[],activeOrder:null,expandedShops:new Set()};
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function readJSON(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function save(){localStorage.setItem('amarCart',JSON.stringify(state.cart))}
function money(n){return '৳'+Number(n||0).toLocaleString('en-BD')}
function configureContactLinks(){document.querySelectorAll('[data-whatsapp-support]').forEach(link=>{if(WA_LINK)link.href=WA_LINK;else{link.href='#support';link.setAttribute('aria-disabled','true')}});document.querySelectorAll('[data-support-phone]').forEach(link=>{if(PHONE)link.href=`tel:${PHONE}`;else{link.href='#support';link.setAttribute('aria-disabled','true')}})}
function icon(name){const paths={rice:'<path d="M7 20c0-5 2-9 5-14 3 5 5 9 5 14M8 15h8M9 11h6M10 7h4"/><path d="M5 20h14"/>',lentil:'<ellipse cx="12" cy="12" rx="8" ry="6"/><path d="M5 11c4-2 10-2 14 1M7 15c3-2 8-2 11 0"/>',oil:'<path d="M9 3h6v3l2 2v13H7V8l2-2V3Z"/><path d="M7 11h10M10 3v3"/>',spice:'<path d="M12 3c1 5 7 7 7 12a7 7 0 0 1-14 0c0-5 5-8 7-12Z"/><path d="M9 16c.5 1.5 1.5 2 3 2"/>',snack:'<path d="M5 8h14l-2 12H7L5 8Z"/><path d="M8 8c0-3 2-5 4-5s4 2 4 5M9 12h.1M14 14h.1"/>',tea:'<path d="M5 8h12v8a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4V8ZM17 10h2a2 2 0 1 1 0 4h-2"/><path d="M8 4c-1 1 1 2 0 3M12 3c-1 1 1 2 0 3"/>',veg:'<path d="M12 20V9M12 12C7 12 5 9 5 6c4 0 7 2 7 6ZM12 10c0-4 3-7 7-7 0 4-2 7-7 7Z"/><path d="M5 20h14"/>',meal:'<path d="M4 13a8 8 0 0 0 16 0H4ZM6 10h12M8 7c0-2 1-3 2-4M13 7c0-2 1-3 2-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',cart:'<path d="M3 4h2l2.2 11.2a2 2 0 0 0 2 1.6h8.6a2 2 0 0 0 2-1.5L22 8H6"/><circle cx="10" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',default:'<path d="M4 7h16v13H4zM8 7V4h8v3M8 12h8"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.default}</svg>`}
function renderCategories(){ $('#categories').innerHTML=categories.map(c=>`<button class="category-chip ${state.category===c.id?'active':''}" data-category="${c.id}"><span>${c.icon}</span>${c.name}</button>`).join('');$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;renderCategories();renderProducts()}) }
function renderProducts(){const q=state.search.trim().toLowerCase();const list=products.filter(p=>(state.category==='all'||(state.category==='restaurants'?p.restaurant:p.category===state.category))&&(!q||(p.name+' '+p.shop+' '+p.category+' '+(p.menuCategory||'')).toLowerCase().includes(q)));const shops=[...new Set(list.filter(p=>p.restaurant).map(p=>p.shop))];const card=(p,i)=>`<article class="product-card" style="animation-delay:${i*25}ms"><div class="product-art" data-kind="${p.kind}"><img src="${escapeHTML(p.image||`assets/products/photos/${p.symbol==='veg'?'vegetables':p.symbol}.jpg`)}" alt="${p.name} photo" loading="lazy"/></div><div class="product-info"><span class="product-shop">${p.shop}</span><h3><button class="product-name-button" data-product-details="${p.id}">${escapeHTML(p.name)}</button></h3><p>${p.priceNote||'Sample price · confirm with shop'}</p><div class="product-bottom"><span class="product-price">${money(p.price)}<small>${p.unit}</small></span><button class="add-button" data-add="${p.id}" aria-label="Add ${p.name} to cart">${icon('plus')}</button></div></div></article>`;const groceries=list.filter(p=>!p.restaurant).map(card).join('');const menus=shops.map(shop=>{const items=list.filter(p=>p.shop===shop);const expanded=state.expandedShops.has(shop)||q.length>0;const featured=items.filter(p=>p.featured);const shown=expanded?items:(featured.length?featured:items).slice(0,3);const cats=[...new Set(shown.map(p=>p.menuCategory||'Menu'))];const sections=expanded?cats.map(cat=>`<section class="menu-category"><h4>${cat}</h4><div class="product-grid">${shown.filter(p=>(p.menuCategory||'Menu')===cat).map(card).join('')}</div></section>`).join(''):`<div class="product-grid featured-products">${shown.map(card).join('')}</div>`;const remaining=Math.max(0,items.length-shown.length);return `<section class="shop-product-group restaurant-group"><div class="shop-group-heading"><div><span class="section-kicker">RESTAURANT PARTNER</span><h3><button class="shop-menu-toggle" data-shop-toggle="${shop}" aria-expanded="${expanded}">${shop}<span aria-hidden="true">${expanded?'−':'+'}</span></button></h3><p>${shop==='Half Time Cafe'?'Prices transcribed from the supplied cafe menu · availability is confirmed by phone.':'Menu sample · availability and final price will be confirmed by phone.'}</p></div><button class="partner-pill menu-toggle-button" data-shop-toggle="${shop}" aria-expanded="${expanded}">${expanded?'CLOSE MENU':'VIEW MENU'}</button></div>${sections}${!expanded&&remaining?`<button class="more-menu-button" data-shop-toggle="${shop}">View ${remaining} more menu items <span>↓</span></button>`:''}</section>`}).join('');$('#products').innerHTML=list.length?groceries+menus:`<div class="no-results">No matching items. Try another search or category.</div>`;$$('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add));$$('[data-shop-toggle]').forEach(b=>b.onclick=()=>{const shop=b.dataset.shopToggle;state.expandedShops.has(shop)?state.expandedShops.delete(shop):state.expandedShops.add(shop);renderProducts()})}
function addToCart(id){const row=state.cart.find(x=>x.id===id);row?row.qty++:state.cart.push({id,qty:1});save();renderCartBadge();toast('Added to your cart');const b=$(`[data-add="${id}"]`);if(b){b.animate([{transform:'scale(1)'},{transform:'scale(1.18) rotate(5deg)'},{transform:'scale(1)'}],{duration:260,easing:'ease-out'})}}
function renderCartBadge(){const n=state.cart.reduce((a,b)=>a+b.qty,0);$('#cartCount').textContent=n;$('#cartOpen').classList.toggle('bump',n>0)}
function itemFor(row){return products.find(p=>p.id===row.id)}
function subtotal(){return state.cart.reduce((sum,row)=>sum+(itemFor(row)?.price||0)*row.qty,0)}
function areaFee(name){return deliveryAreas.find(a=>a.id===name||a.name===name)?.fee??null}
function updateCheckoutEstimate(){const area=$('#custArea')?.value;const fee=areaFee(area);if($('#deliveryFeeValue'))$('#deliveryFeeValue').textContent=fee===null?'Choose area':money(fee);if($('#estimatedTotal'))$('#estimatedTotal').textContent=fee===null?'Choose area':money(subtotal()+fee)}
function setQty(id,d){const r=state.cart.find(x=>x.id===id);if(r){r.qty+=d;if(r.qty<1)state.cart=state.cart.filter(x=>x.id!==id);save();renderCart()}}
function renderCart(){renderCartBadge();const body=$('#cartBody'),foot=$('#cartFoot');if(!state.cart.length){body.innerHTML=`<div class="empty-cart"><div class="empty-icon">${icon('cart')}</div><h3>Your cart is taking a little break.</h3><p>Browse the preview catalog and add a demo item to see how checkout works.</p><a class="button primary" href="#market" data-close>Explore market <span>↗</span></a></div>`;foot.innerHTML='';return}body.innerHTML=state.cart.map(row=>{const p=itemFor(row);return `<div class="cart-line"><div class="mini-art">${icon(p.symbol)}</div><div><h4>${p.name}</h4><small>${money(p.price)} · demo listing</small><div class="line-controls"><button data-qty="${p.id}" data-delta="-1" aria-label="Remove one">−</button><span>${row.qty}</span><button data-qty="${p.id}" data-delta="1" aria-label="Add one">+</button></div></div><span class="line-price">${money(p.price*row.qty)}</span></div>`}).join('')+`<div class="checkout-notice">This is a demo catalog. In the pilot, the team will verify each item and price with the shop before asking for your approval.</div>`;foot.innerHTML=`<div class="cart-total"><span>Preview subtotal</span><b>${money(subtotal())}</b></div><div class="cart-total"><span>Delivery fee</span><span>Confirmed by staff</span></div><div class="cart-total grand"><span>Total after verification</span><span>To be confirmed</span></div><button class="button primary full" id="goCheckout">Continue to delivery details <span>→</span></button>`;$$('[data-qty]').forEach(b=>b.onclick=()=>setQty(b.dataset.qty,+b.dataset.delta));$('#goCheckout').onclick=openCheckout}
function openPanel(id){$('#overlay').hidden=false;requestAnimationFrame(()=>$('#overlay').classList.add('visible'));$(`#${id}`).classList.add('open');$(`#${id}`).setAttribute('aria-hidden','false');document.body.classList.add('locked')}
function closePanels(){$$('.drawer.open,.modal.open').forEach(p=>{p.classList.remove('open');p.setAttribute('aria-hidden','true')});$('#overlay').classList.remove('visible');setTimeout(()=>$('#overlay').hidden=true,220);document.body.classList.remove('locked')}
function openCart(){renderCart();openPanel('cartDrawer')}
function openCheckout(){closePanels();setTimeout(()=>{renderCheckout();openPanel('checkoutModal')},180)}
function renderCheckout(){const c=$('#checkoutContent');c.innerHTML=`<form class="checkout-form" id="checkoutForm"><div class="confirm-card"><h3>Review your order request</h3><p>Check the items and estimated total, then open WhatsApp and press Send. Availability, prices and delivery charge are confirmed by our team. Opening WhatsApp alone does not submit or confirm your order.</p></div><div class="form-grid"><div class="field"><label for="custName">Your name *</label><input id="custName" name="name" maxlength="100" required autocomplete="name" placeholder="Full name"/></div><div class="field"><label for="custPhone">Mobile number *</label><input id="custPhone" name="phone" maxlength="20" required inputmode="tel" autocomplete="tel" placeholder="01XXXXXXXXX" pattern="(?:\\+?88)?01[3-9]\\d{8}"/></div></div><div id="otpSlot"></div><div class="form-grid"><div class="field"><label for="custArea">Choose delivery area *</label><select id="custArea" name="area" required><option value="">Choose your area</option>${deliveryAreas.map(a=>`<option value="${a.id||a.name}" data-fee="${a.fee}" data-area-id="${a.id||''}">${escapeHTML(a.name)} · ${money(a.fee)}</option>`).join("")}</select></div><div class="field"><label for="custLandmark">Landmark (optional)</label><input id="custLandmark" name="landmark" maxlength="200" placeholder="Nearby school, mosque, etc."/></div></div><div class="field"><label for="custAddress">Delivery address *</label><textarea id="custAddress" name="address" maxlength="500" required placeholder="House, road, and directions"></textarea></div><div class="location-picker"><div class="location-picker-head"><div><b>Share delivery location (optional)</b><small>Only used if you choose to share it. You can also type your address above.</small></div><button class="button ghost" type="button" id="useLocation">Use my location</button></div><div class="location-result" id="locationResult">No location shared</div></div><div class="field"><label for="custNote">Delivery instructions (optional)</label><input id="custNote" name="note" maxlength="300" placeholder="Anything our delivery team should know?"/></div><div id="formError"></div><p class="form-hint">Prices and fees shown here are estimates from the current catalog. The shop and delivery team must confirm the final order with you.</p><div class="summary-row"><span>Requested items</span><strong>${state.cart.reduce((a,b)=>a+b.qty,0)} items</strong></div><div class="summary-row"><span>Product subtotal</span><strong>${money(subtotal())} · estimate</strong></div><div class="summary-row"><span>Area delivery charge</span><strong id="deliveryFeeValue">Choose area</strong></div><div class="summary-row grand"><span>Estimated total</span><strong id="estimatedTotal">Choose area</strong></div><button class="button whatsapp-order-button full" id="whatsappOrder" type="button"><span aria-hidden="true">◉</span> Place order via WhatsApp</button>${backend.backendConfigured?'<button class="button ghost full secondary-order-button" type="submit">Use verified online checkout</button>':''}<div id="whatsappHandoff" aria-live="polite"></div><p class="form-hint">WhatsApp opens with your order message. Review it and press Send. Your cart stays here, and the order is not confirmed until Amar Bazar receives and verifies it.</p></form>`;$('#checkoutForm').onsubmit=submitOrder;$('#whatsappOrder').onclick=()=>submitWhatsAppOrder();document.getElementById("custArea").addEventListener("change",updateCheckoutEstimate);$('#useLocation').onclick=()=>{const result=$('#locationResult');if(!navigator.geolocation){result.textContent='Location sharing is not available here. Please enter your address manually.';return}result.textContent='Waiting for location permission…';navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude.toFixed(6),lng=pos.coords.longitude.toFixed(6);$('#checkoutForm').dataset.lat=lat;$('#checkoutForm').dataset.lng=lng;result.innerHTML=`Location attached: ${lat}, ${lng} · <a href="https://www.google.com/maps?q=${lat},${lng}" target="_blank" rel="noreferrer">View map ↗</a>`},()=>{result.textContent='Could not get your location. Please enter your address manually.'},{enableHighAccuracy:true,timeout:12000})}}
function messageForWhatsApp({data,area,reference,items=state.cart,productRows=products}){return buildWhatsAppOrderMessage({customer:{name:data.get('name'),phone:data.get('phone'),address:data.get('address'),instructions:data.get('note')},cart:items,products:productRows,deliveryArea:area,reference,createdAt:new Date()})}
function ensureWhatsAppReference(fingerprint){if(fingerprint!==whatsappDraftFingerprint){whatsappDraftFingerprint=fingerprint;whatsappDraftReference=createTemporaryOrderReference()}return whatsappDraftReference}
function ensureWhatsAppIdempotencyKey(fingerprint){if(fingerprint!==whatsappRequestFingerprint){whatsappRequestFingerprint=fingerprint;whatsappOrderIdempotencyKey=globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}return whatsappOrderIdempotencyKey}
function showWhatsAppFallback(message,reason,persisted=false){const host=$('#whatsappHandoff');const supportLink=webConfig.whatsappSupportLink;host.innerHTML=`<div class="confirm-card whatsapp-handoff-card"><h3>Order message ready</h3><p>${escapeHTML(reason)}. Copy this message, open the Amar Bazar WhatsApp chat, paste it and press Send. ${persisted?'The order is saved as Pending WhatsApp send; staff will verify it only after receiving your message.':'This reference is temporary and no order is saved in this preview.'}</p><textarea id="whatsappMessageCopy" readonly rows="9" aria-label="Order message to copy">${escapeHTML(message)}</textarea><div class="support-actions"><button class="button ghost" id="copyWhatsAppMessage" type="button">Copy order message</button>${supportLink?`<a class="button whatsapp-order-button" href="${escapeHTML(supportLink)}" target="_blank" rel="noopener noreferrer">Open Amar Bazar WhatsApp</a>`:`<a class="button ghost" href="tel:${encodeURIComponent(PHONE)}">Call support</a>`}</div></div>`;$('#copyWhatsAppMessage').onclick=()=>copyWhatsAppMessage()}
async function copyWhatsAppMessage(){const field=$('#whatsappMessageCopy');if(!field)return;try{await navigator.clipboard.writeText(field.value);toast('Order message copied. Paste it in WhatsApp and press Send.')}catch{field.focus();field.select();toast('Select and copy the order message, then paste it in WhatsApp.')}}
async function submitWhatsAppOrder(){const form=$('#checkoutForm');if(!form.reportValidity())return;const data=new FormData(form),errorBox=$('#formError'),area=deliveryAreas.find(item=>item.id===data.get('area')||item.name===data.get('area'));errorBox.innerHTML='';if(!state.cart.length){errorBox.innerHTML='<div class="form-error">Your cart is empty. Add a product before placing an order.</div>';return}if(!area){errorBox.innerHTML='<div class="form-error">Choose a delivery area to calculate the estimated delivery charge.</div>';return}let phone;try{phone=backend.normalizedBangladeshPhone(data.get('phone'))}catch{errorBox.innerHTML='<div class="form-error">Enter a valid Bangladesh mobile number.</div>';return}const fingerprint=JSON.stringify({name:data.get('name'),phone,area:area.id||area.name,address:data.get('address'),note:data.get('note'),items:state.cart});let reference='',message='',persisted=false;try{if(backend.backendConfigured){if(!backendSettings?.orders_enabled)throw new Error('ORDERS_DISABLED');if(!backend.currentSession()?.access_token){if(otpRequestedFor!==phone){await backend.requestPhoneCode(phone);otpRequestedFor=phone;$('#otpSlot').innerHTML='<div class="field otp-field"><label for="otpCode">SMS verification code *</label><input id="otpCode" name="otpCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{4,8}" required placeholder="Enter the code we sent"><small>Verify your phone to save a secure draft before WhatsApp opens.</small></div>';toast('Verification code sent. Enter it to continue.');return}await backend.verifyPhoneCode(phone,data.get('otpCode'))}const draftKey=ensureWhatsAppIdempotencyKey(fingerprint);const draft=await backend.createWhatsAppOrderDraft({name:data.get('name'),phone,areaId:area.id,address:data.get('address'),landmark:data.get('landmark'),note:data.get('note'),coordinates:form.dataset.lat?{lat:Number(form.dataset.lat),lng:Number(form.dataset.lng)}:null,items:state.cart,idempotencyKey:draftKey});const order=await backend.getOrder(draft.orderId);if(!order)throw new Error('ORDER_DRAFT_LOAD_FAILED');reference=order.public_code;const serverItems=order.items.map(item=>({id:item.product_id,qty:Number(item.quantity)}));const serverProducts=order.items.map(item=>{const catalogProduct=products.find(product=>product.id===item.product_id);return{id:item.product_id,name:item.requested_name,shop:catalogProduct?.shop||'Amar Bazar partner',unit:item.requested_unit_label,price:Number(item.requested_unit_price)}});message=messageForWhatsApp({data,area:{id:area.id,name:order.area_name_snapshot,fee:Number(order.estimated_delivery_fee)},reference,items:serverItems,productRows:serverProducts});whatsappDraftFingerprint=fingerprint;persisted=true}else{reference=ensureWhatsAppReference(fingerprint);message=messageForWhatsApp({data,area,reference})}}catch(error){const messages={ORDERS_DISABLED:'Online ordering is paused. Please contact our team.',AUTH_REQUIRED:'Phone verification is required. Request a new code and try again.',ITEM_UNAVAILABLE:'A product is no longer available. Refresh the catalog and review your basket.',STOCK_CONFLICT:'The requested quantity is not available. Refresh the catalog and review your basket.',AREA_UNAVAILABLE:'Delivery is temporarily unavailable in this area.',ORDER_DRAFT_LOAD_FAILED:'The draft was saved, but its verified details could not be loaded. Retry using the same details.'};errorBox.innerHTML=`<div class="form-error">${escapeHTML(messages[error.message]||'We could not prepare your order. Your cart is still saved. Check your connection and retry safely.')}</div>`;return}let url;try{url=buildWhatsAppOrderUrl(webConfig.whatsappBusinessNumber,message)}catch(error){if(error.message==='WHATSAPP_NUMBER_NOT_CONFIGURED'||error.message==='MESSAGE_TOO_LONG'){showWhatsAppFallback(message,error.message==='MESSAGE_TOO_LONG'?'This message is too long for a WhatsApp link':'The WhatsApp Business number is not configured',persisted);navigator.clipboard?.writeText(message).catch(()=>{});return}errorBox.innerHTML='<div class="form-error">WhatsApp could not be opened. Please call support or try again.</div>';return}const popup=window.open(url,'_blank');if(popup)popup.opener=null;const host=$('#whatsappHandoff');host.innerHTML=`<div class="confirm-card whatsapp-handoff-card"><h3>WhatsApp is opening</h3><p>Review the message in WhatsApp and press Send. ${persisted?'Your order is saved as Pending WhatsApp send, not confirmed. Staff will verify it after receiving the message.':'Amar Bazar has not received or confirmed this temporary preview request.'}</p><a class="button whatsapp-order-button" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">Open WhatsApp again</a></div>`}
async function submitOrder(e){
  e.preventDefault();
  const form=e.currentTarget, data=new FormData(form), errorBox=$('#formError');
  errorBox.innerHTML='';
  if(!backend.backendConfigured){errorBox.innerHTML='<div class="form-error">Live ordering is not enabled yet. The catalog preview cannot submit or save a real order.</div>';return}
  if(!backendSettings?.orders_enabled){errorBox.innerHTML='<div class="form-error">Online ordering is temporarily paused. Please contact our team.</div>';return}
  let phone;
  try{phone=backend.normalizedBangladeshPhone(data.get('phone'))}catch{errorBox.innerHTML='<div class="form-error">Enter a valid Bangladesh mobile number.</div>';return}
  const area=deliveryAreas.find(item=>item.id===data.get('area')||item.name===data.get('area'));
  if(!area||!state.cart.length||state.cart.some(line=>!itemFor(line))){errorBox.innerHTML='<div class="form-error">Choose a delivery area and review available products in your basket.</div>';return}
  try{
    if(!backend.currentSession()?.access_token){
      if(otpRequestedFor!==phone){await backend.requestPhoneCode(phone);otpRequestedFor=phone;$('#otpSlot').innerHTML='<div class="field otp-field"><label for="otpCode">SMS verification code *</label><input id="otpCode" name="otpCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{4,8}" required placeholder="Enter the code we sent"><small>Verify your phone before the order request is sent.</small></div>';toast('Verification code sent. Check your phone.');return}
      await backend.verifyPhoneCode(phone,data.get('otpCode'));
    }
    if(!orderIdempotencyKey){orderIdempotencyKey=(crypto.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)}));sessionStorage.setItem('amarOrderRequestKey',orderIdempotencyKey)}
    const result=await backend.createOrder({name:data.get('name'),phone,areaId:area.id,address:data.get('address'),landmark:data.get('landmark'),note:data.get('note'),coordinates:form.dataset.lat?{lat:Number(form.dataset.lat),lng:Number(form.dataset.lng)}:null,items:state.cart,idempotencyKey:orderIdempotencyKey});
    let order;try{order=await backend.getOrder(result.orderId)}catch{order=null}
    if(!order)order={id:result.orderId,public_code:result.publicCode,status:result.status,area_name_snapshot:area.name,recipient_name_snapshot:data.get('name'),phone_snapshot:phone,address_snapshot:data.get('address'),estimated_total:result.estimatedTotal,final_total:null,items:state.cart.map(line=>({requested_name:itemFor(line)?.name||'Item',quantity:line.qty,requested_unit_label:itemFor(line)?.unit||'',requested_unit_price:itemFor(line)?.price||0,fulfillment_state:'pending'})),history:[]};
    state.cart=[];save();renderCartBadge();renderCart();otpRequestedFor='';orderIdempotencyKey='';sessionStorage.removeItem('amarOrderRequestKey');closePanels();
    setTimeout(()=>{renderLiveOrder(order);openPanel('orderModal')},220);
  }catch(error){const msg=error?.message||'ORDER_SUBMISSION_FAILED';errorBox.innerHTML=`<div class="form-error">${escapeHTML(msg==='ITEM_UNAVAILABLE'||msg==='STOCK_CONFLICT'?'A product or quantity is no longer available. Refresh the catalog and review your basket.':msg==='AUTH_REQUIRED'?'Please verify your phone number before submitting the order.':msg==='ORDERS_DISABLED'?'Online ordering is temporarily paused. Please contact our team.':'We could not submit the order. Your basket is still saved. Check your connection and retry safely.')}</div>`}
}
const liveStatusLabels={pending_submission:'Waiting for WhatsApp send',pending_verification:'Waiting for shop verification',awaiting_customer_approval:'Your approval needed',confirmed:'Confirmed',preparing:'Being prepared',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Cancelled',rejected:'Declined',expired:'Expired'};
async function renderLiveOrder(order){if(!order){$('#orderContent').innerHTML='<p class="empty-cart">We could not load this order. Open your account to refresh order history.</p>';return}const items=(order.items||[]).map(item=>`<div class="summary-row"><span>${escapeHTML(item.fulfilled_name||item.requested_name)} × ${item.quantity} <small>${escapeHTML(item.fulfillment_state)}</small></span><strong>${item.final_unit_price==null?'To be confirmed':money(Number(item.final_unit_price)*Number(item.quantity))}</strong></div>`).join('');const total=order.final_total??order.estimated_total;const history=(order.history||[]).map(event=>`<li class="done"><b>${escapeHTML(liveStatusLabels[event.to_status]||event.to_status)}</b><small>${new Date(event.created_at).toLocaleString('en-BD')}</small></li>`).join('');const canDecide=order.status==='awaiting_customer_approval';const intro=order.status==='pending_submission'?'This draft is saved, but it is not yet a received order. Open WhatsApp, review the message and press Send. Staff will start checking it only after receiving your message.':'This request is saved to your account. Our team verifies shop stock and pricing before confirming it.';$('#orderContent').innerHTML=`<div class="modal-content"><span class="order-ref">${escapeHTML(order.public_code)}</span><div class="confirm-card"><h3>${escapeHTML(liveStatusLabels[order.status]||order.status)}</h3><p>${intro}</p></div>${items}<div class="summary-row"><span>Delivery · ${escapeHTML(order.area_name_snapshot)}</span><strong>${order.final_delivery_fee==null?'To be confirmed':money(order.final_delivery_fee)}</strong></div><div class="summary-row grand"><span>${order.final_total==null?'Estimated':'Final'} total</span><strong>${money(total)}</strong></div>${canDecide?`<div class="confirm-card"><h3>Review the shop-checked order</h3><p>Approve to confirm and reserve the checked products. Rejecting this quote cancels the order.</p><div class="approval-actions"><button class="button primary" id="liveApprove">Approve final order</button><button class="button danger" id="liveReject">Reject and cancel</button></div></div>`:''}<h3>Order history</h3><ol class="timeline">${history||`<li class="done">${escapeHTML(liveStatusLabels[order.status]||order.status)}</li>`}</ol><p class="form-hint">For help, <a href="${WA_LINK}" target="_blank" rel="noreferrer">message us on WhatsApp</a> or <a href="tel:${PHONE}">call support</a>.</p></div>`;for(const [id,decision] of [['liveApprove','approved'],['liveReject','rejected']])$('#'+id)?.addEventListener('click',async()=>{const button=$('#'+id);button.disabled=true;try{await backend.decideQuote(order.id,order.quote_version,decision);const updated=await backend.getOrder(order.id);renderLiveOrder(updated);toast(decision==='approved'?'Order confirmed':'Quote rejected and order cancelled')}catch(err){toast(err.message==='QUOTE_STALE'?'This quote changed. Refresh your order before deciding.':'We could not save your decision. Please retry.');button.disabled=false}})}
const statuses=['Order received','Checking availability and prices with the shop','Waiting for your approval','Order confirmed','Being prepared','Out for delivery','Completed'];
function renderOrder(order){if(!order)return;const checked=order.verifiedItems||order.items;const total=checked.reduce((a,i)=>a+(i.available===false?0:i.price*i.qty),0)+(order.deliveryFee||0);$('#orderContent').innerHTML=`<div class="modal-content"><span class="order-ref">${order.id}</span><div class="confirm-card"><h3>${order.status}</h3><p>We’ll contact you at ${escapeHTML(order.phone)} shortly after checking availability and prices with the shops. Please keep your phone available for our confirmation call. Keep your order reference handy.</p></div><div class="summary-row"><span>Requested items</span><strong>${order.items.reduce((a,i)=>a+i.qty,0)}</strong></div>${checked.map(i=>`<div class="summary-row"><span>${escapeHTML(i.name)}${i.alternative?' → '+escapeHTML(i.alternative):''} × ${i.qty}${i.available===false?' · unavailable':''}</span><strong>${i.available===false?'—':money(i.price*i.qty)}</strong></div>`).join('')}${order.verified?`<div class="summary-row"><span>Delivery fee</span><strong>${order.deliveryFee?money(order.deliveryFee):'To be confirmed'}</strong></div><div class="summary-row"><span>Estimated delivery</span><strong>${escapeHTML(order.eta||'To be confirmed')}</strong></div><div class="summary-row grand"><span>Verified total</span><strong>${money(total)}</strong></div>`:`<div class="summary-row"><span>Estimated area delivery fee</span><strong>${money(order.deliveryFee||0)}</strong></div><div class="summary-row grand"><span>Estimated total</span><strong>${money(order.estimatedTotal||total)}</strong></div><p class="form-hint">Pilot sample prices and area fee. We will call shortly to confirm availability, final prices and your order.</p>`}<ol class="timeline">${statuses.map((s,i)=>{const idx=statuses.indexOf(order.status);const current=order.status==='Waiting for your approval'&&s==='Waiting for your approval';return `<li class="${i<=idx||current?'done':''} ${current?'current':''}">${s}</li>`}).join('')}</ol>${order.status==='Waiting for your approval'?`<div class="confirm-card"><h3>Review the verified order</h3><p>This is a local prototype. Review the sample verification and approve to see the next step. No real shop check or message has taken place.</p><div class="approval-actions"><button class="button primary" id="customerApprove">Approve order</button><button class="button ghost" id="customerChange">Request a change</button><button class="button danger" id="customerCancel">Cancel</button></div></div>`:''}<div class="support-actions" style="display:flex;flex-direction:row;margin-top:14px"><a class="button ghost" href="${WA_LINK}" target="_blank" rel="noreferrer">WhatsApp support ↗</a><a class="button ghost" href="tel:${PHONE}">Call support ↗</a></div></div>`;$('#customerApprove')?.addEventListener('click',()=>{order.approved=true;order.status='Order confirmed';order.log.push({status:order.status,at:new Date().toISOString(),source:'Customer preview action'});save();renderOrder(order);toast('Approval recorded in this preview')});$('#customerChange')?.addEventListener('click',()=>toast('Contact staff to request a change'));$('#customerCancel')?.addEventListener('click',()=>{order.status='Cancelled';order.log.push({status:order.status,at:new Date().toISOString()});save();renderOrder(order);toast('Order cancelled in this preview')})}
function renderAdmin(){const c=$('#adminContent');if(!state.orders.length){c.innerHTML=`<div class="staff-lock"><div class="confirm-card"><h3>Preview staff tools</h3><p>This local prototype has no connected staff accounts or live database. Add confirmed shop and product details in the production admin system before taking real orders.</p></div><div class="staff-empty">No preview orders yet.<br/>Place a demo order to see the verification queue.</div></div>`;return}c.innerHTML=`<div class="staff-list">${state.orders.map(o=>`<article class="staff-order"><div class="staff-order-top"><div><h3>${o.id} · ${escapeHTML(o.name)}</h3><small>${escapeHTML(o.area)} · ${escapeHTML(o.phone)}</small></div><span class="staff-status">${escapeHTML(o.status)}</span></div><div class="staff-items">${o.items.map(i=>`${escapeHTML(i.name)} × ${i.qty}`).join(' · ')}<br/>Address: ${escapeHTML(o.address)}${o.landmark?' · '+escapeHTML(o.landmark):''}${o.coordinates?`<br/><a target="_blank" rel="noreferrer" href="https://www.google.com/maps?q=${o.coordinates.lat},${o.coordinates.lng}">Open customer pin in Google Maps ↗</a>`:''}</div><div class="staff-tools"><a href="tel:${escapeHTML(o.phone)}">Call customer</a><a target="_blank" rel="noreferrer" href="${WA_LINK}">WhatsApp</a><button data-start="${o.id}">Start shop check</button><button data-review="${o.id}">Save verification & request approval</button><button data-prepare="${o.id}">Mark preparing</button></div><div class="verify-form"><b>Shop check (demo)</b>${o.items.map((i,n)=>`<div class="verify-row"><span>${escapeHTML(i.name)} × ${i.qty}</span><label><input type="checkbox" data-available="${o.id}" data-index="${n}" checked> Available</label><input type="number" min="0" step="1" data-price="${o.id}" data-index="${n}" value="${i.price}" aria-label="Verified unit price for ${escapeHTML(i.name)}"><input type="text" data-alternative="${o.id}" data-index="${n}" placeholder="Alternative (optional)"></div>`).join('')}<div class="form-grid"><div class="field"><label>Delivery fee (demo)</label><input type="number" min="0" data-fee="${o.id}" placeholder="Leave blank if unknown" value="${o.deliveryFee??''}"></div><div class="field"><label>Estimated delivery time</label><input type="text" data-eta="${o.id}" placeholder="e.g. 45–60 minutes" value="${escapeHTML(o.eta||'')}"></div></div><small>Only use real shop-confirmed data in production.</small></div></article>`).join('')}</div>`;$$('[data-start]').forEach(b=>b.onclick=()=>{const o=state.orders.find(x=>x.id===b.dataset.start);o.status='Checking availability and prices with the shop';o.log.push({status:o.status,at:new Date().toISOString(),source:'Local staff preview action'});save();renderAdmin();if(state.activeOrder===o.id)renderOrder(o);toast('Shop check started in preview')});$$('[data-review]').forEach(b=>b.onclick=()=>{const o=state.orders.find(x=>x.id===b.dataset.review);const verified=[];for(let i=0;i<o.items.length;i++){const available=$(`[data-available="${o.id}"][data-index="${i}"]`).checked;const raw=$(`[data-price="${o.id}"][data-index="${i}"]`).value;const price=Number(raw);if(available&&(!raw||!Number.isFinite(price)||price<0)){toast('Enter a valid verified price for every available item');return}verified.push({...o.items[i],available,price,alternative:$(`[data-alternative="${o.id}"][data-index="${i}"]`).value.trim()})}o.verifiedItems=verified;o.deliveryFee=Number($(`[data-fee="${o.id}"]`).value)||0;o.eta=$(`[data-eta="${o.id}"]`).value.trim();o.verified=true;o.status='Waiting for your approval';o.log.push({status:o.status,at:new Date().toISOString(),source:'Local staff preview action'});save();renderAdmin();if(state.activeOrder===o.id)renderOrder(o);toast('Final summary is ready for customer approval')});$$('[data-prepare]').forEach(b=>b.onclick=()=>{const o=state.orders.find(x=>x.id===b.dataset.prepare);if(!o.approved){toast('Customer approval is required before preparation');return}o.status='Being prepared';o.log.push({status:o.status,at:new Date().toISOString(),source:'Local staff preview action'});save();renderAdmin();if(state.activeOrder===o.id)renderOrder(o)})}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let toastTimer;function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
$('#searchInput').addEventListener('input',e=>{state.search=e.target.value;renderProducts()});$('#cartOpen').addEventListener('click',openCart);$('#adminOpen').addEventListener('click',()=>{renderAdmin();openPanel('adminModal')});$('#overlay').addEventListener('click',closePanels);$$('[data-close]').forEach(b=>b.addEventListener('click',e=>{if(e.target.closest('a'))closePanels();else closePanels()}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanels()});$('#cartOpen').addEventListener('animationend',()=>$('#cartOpen').classList.remove('bump'));
renderCategories();renderProducts();renderCartBadge();

function statusLabel(status){return liveStatusLabels[status]||status}
async function renderAccount(){const root=$('#accountContent');if(!backend.backendConfigured){root.innerHTML='<div class="modal-content"><div class="confirm-card"><h3>Customer account is not connected</h3><p>The current catalog is a preview. Connect a local or staging Supabase project to enable secure sign-in, saved addresses and real order history.</p></div></div>';return}const session=backend.currentSession();if(!session?.access_token){root.innerHTML=`<form class="modal-content checkout-form" id="accountLogin"><div class="confirm-card"><h3>Sign in with your phone</h3><p>We will send a one-time code. Your order history and saved addresses are private to your account.</p></div><div class="field"><label for="accountPhone">Bangladesh mobile number</label><input id="accountPhone" name="phone" required inputmode="tel" autocomplete="tel" placeholder="01XXXXXXXXX" /></div><div id="accountOtp"></div><div id="accountError"></div><button class="button primary full" type="submit" id="accountContinue">Send verification code</button></form>`;$('#accountLogin').onsubmit=async(e)=>{e.preventDefault();const phone=$('#accountPhone').value;const error=$('#accountError');try{if(!$('#accountOtp input')){await backend.requestPhoneCode(phone);$('#accountOtp').innerHTML='<div class="field"><label for="accountCode">Verification code</label><input id="accountCode" name="code" required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{4,8}" /></div>';$('#accountContinue').textContent='Verify and sign in';toast('Verification code sent. Check your phone.');return}await backend.verifyPhoneCode(phone,$('#accountCode').value);await renderAccount()}catch(err){error.innerHTML='<div class="form-error">We could not verify that phone number. Check the number/code and try again.</div>'}};return}
  root.innerHTML='<div class="modal-content"><div class="loading-inline">Loading your private account…</div></div>';try{const [profile,addresses]=await Promise.all([backend.getMyProfile(),backend.listMyAddresses()]);root.innerHTML=`<div class="modal-content"><div class="confirm-card"><h3>Signed in</h3><p>${escapeHTML(profile.phone_e164||'Your verified phone')}</p></div><form class="checkout-form" id="profileForm"><div class="field"><label for="profileName">Your name</label><input id="profileName" maxlength="100" required value="${escapeHTML(profile.display_name||'')}" /></div><button class="button ghost" type="submit">Save profile</button></form><div class="panel-heading"><div><h3>Saved delivery addresses</h3></div><button class="button ghost" id="historyOpen">Order history</button></div><div class="address-list">${addresses.length?addresses.map(a=>`<div class="summary-row"><span><b>${escapeHTML(a.label)}</b> · ${escapeHTML(a.recipient_name)}<small>${escapeHTML(a.address_line)} · ${escapeHTML(a.phone_e164)}</small></span><button class="button ghost" data-delete-address="${a.id}">Remove</button></div>`).join(''):'<p class="form-hint">No saved addresses yet.</p>'}</div><form class="checkout-form" id="addressForm"><h3>Add a delivery address</h3><div class="form-grid"><div class="field"><label>Label</label><input name="label" value="Home" maxlength="60" required /></div><div class="field"><label>Recipient name</label><input name="name" maxlength="100" required value="${escapeHTML(profile.display_name||'')}" /></div></div><div class="form-grid"><div class="field"><label>Phone</label><input name="phone" value="${escapeHTML(profile.phone_e164||'')}" required /></div><div class="field"><label>Delivery area</label><select name="areaId" required>${deliveryAreas.map(a=>`<option value="${a.id}">${escapeHTML(a.name)}</option>`).join('')}</select></div></div><div class="field"><label>House, road and address</label><textarea name="line" maxlength="500" required></textarea></div><div class="field"><label>Landmark (optional)</label><input name="landmark" maxlength="200" /></div><button class="button primary" type="submit" ${deliveryAreas.some(a=>a.id)?'':'disabled'}>Save address</button></form><button class="button ghost" id="signOut">Sign out</button></div>`;$('#profileForm').onsubmit=async e=>{e.preventDefault();try{await backend.updateMyProfile($('#profileName').value);toast('Profile saved')}catch{toast('Could not save profile')}};$('#addressForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{await backend.saveMyAddress({label:form.get('label'),name:form.get('name'),phone:form.get('phone'),areaId:form.get('areaId'),line:form.get('line'),landmark:form.get('landmark')});toast('Address saved securely');await renderAccount()}catch{toast('Could not save address. Check the phone and area.')}};$$('[data-delete-address]').forEach(button=>button.onclick=async()=>{if(!confirm('Remove this saved address?'))return;try{await backend.deleteMyAddress(button.dataset.deleteAddress);await renderAccount()}catch{toast('Could not remove address')}});$('#historyOpen').onclick=()=>{closePanels();setTimeout(()=>{openPanel('historyModal');void renderHistory()},180)};$('#signOut').onclick=()=>{backend.signOut();renderAccount()}}catch{root.innerHTML='<div class="modal-content"><div class="form-error">We could not load your account data. Please retry when your connection is available.</div><button class="button ghost" id="accountRetry">Retry</button></div>';$('#accountRetry').onclick=()=>void renderAccount()}}
async function renderHistory(){const root=$('#historyContent');if(!backend.currentSession()?.access_token){root.innerHTML='<p class="form-hint">Sign in to view private order history.</p>';return}root.innerHTML='<div class="modal-content"><div class="loading-inline">Loading your orders…</div></div>';try{const orders=await backend.listMyOrders();root.innerHTML=`<div class="modal-content">${orders.length?orders.map(order=>`<button class="history-order" data-order-id="${order.id}"><span><b>${escapeHTML(order.public_code)}</b><small>${escapeHTML(order.area_name_snapshot)} · ${new Date(order.created_at).toLocaleString('en-BD')}</small></span><span><b>${statusLabel(order.status)}</b><small>${money(order.final_total??order.estimated_total)}</small></span></button>`).join(''):'<div class="empty-cart"><h3>No orders yet</h3><p>Real order requests will appear here.</p></div>'}</div>`;$$('[data-order-id]').forEach(button=>button.onclick=async()=>{try{const order=await backend.getOrder(button.dataset.orderId);closePanels();setTimeout(()=>{renderLiveOrder(order);openPanel('orderModal')},180)}catch{toast('Could not load this order')}})}catch{root.innerHTML='<div class="modal-content"><div class="form-error">Order history could not be loaded. Please retry.</div><button class="button ghost" id="historyRetry">Retry</button></div>';$('#historyRetry').onclick=()=>void renderHistory()}}
async function initializeLiveCatalog(){if(!backend.backendConfigured){const note=$('.catalog-note');if(note)note.innerHTML='<span class="note-dot"></span><span><b>Preview catalog</b> — sample listings are shown. Real checkout is disabled until a Supabase environment is connected.</span>';return}const note=$('.catalog-note');if(note)note.innerHTML='<span class="note-dot"></span><span><b>Loading live catalog</b> — product prices, availability and delivery areas come from the shared database.</span>';try{const data=await backend.loadCatalog();products=data.products.map(p=>({...p,restaurant:/restaurant|cafe|food|meal/.test(`${p.category} ${p.shop.toLowerCase()}`),featured:false,kind:'food',symbol:'meal',priceNote:'Shop listing · final price is verified before confirmation'}));categories=[{id:'all',name:'Everything',icon:'✳'},...data.categories];deliveryAreas=data.deliveryAreas;backendSettings=data.settings;catalogReady=true;const availableIds=new Set(products.map(p=>p.id));if(state.cart.some(line=>!availableIds.has(line.id))){state.cart=state.cart.filter(line=>availableIds.has(line.id));save()}renderCategories();renderProducts();renderCartBadge();const settings=data.settings||{};if(note)note.innerHTML=`<span class="note-dot"></span><span><b>${settings.orders_enabled?'Live catalog':'Catalog preview · ordering paused'}</b> — current listings come from Amar Bazar's shared catalog. Shops confirm availability and final order totals.</span>`;document.title=`${settings.display_name||'Amar Bazar'} — Local market, delivered`}catch(error){catalogError=error.message||'CATALOG_UNAVAILABLE';products=[];catalogReady=false;renderCategories();renderProducts();const note=$('.catalog-note');if(note)note.innerHTML='<span class="note-dot"></span><span><b>Catalog temporarily unavailable</b> — retry when the connection is restored. Sample prices are hidden while live mode is configured.</span>';toast('Could not load live product data')}}
const renderLiveOrderBase=renderLiveOrder;
renderLiveOrder=async function(order){await renderLiveOrderBase(order);const content=$('#orderContent .modal-content');if(!content)return;const refresh=document.createElement('button');refresh.className='button ghost';refresh.textContent='Refresh order status';refresh.onclick=async()=>{try{renderLiveOrder(await backend.getOrder(order.id))}catch{toast('Could not refresh this order')}};content.append(refresh);if(['pending_submission','pending_verification','awaiting_customer_approval'].includes(order.status)){const cancel=document.createElement('button');cancel.className='button ghost';cancel.textContent='Cancel request';cancel.onclick=async()=>{if(!confirm('Cancel this order request?'))return;cancel.disabled=true;try{await backend.cancelOrder(order.id);renderLiveOrder(await backend.getOrder(order.id));toast('Order request cancelled')}catch(error){toast(error.message==='INVALID_TRANSITION'?'This order can no longer be cancelled here. Contact support.':'Could not cancel this request. Please retry.');cancel.disabled=false}};content.append(cancel)}};
$('#accountOpen').addEventListener('click',()=>{void renderAccount();openPanel('accountModal')});
$('#products').addEventListener('click',event=>{const button=event.target.closest('[data-product-details]');if(!button)return;const product=products.find(item=>item.id===button.dataset.productDetails);if(!product)return;$('#productContent').innerHTML=`<div class="modal-content">${product.image?`<img class="product-detail-image" src="${escapeHTML(product.image)}" alt="${escapeHTML(product.name)}">`:''}<span class="section-kicker">${escapeHTML(product.shop)}</span><h3>${escapeHTML(product.name)}</h3><p>${escapeHTML(product.description||'Availability and current price will be verified with the shop.')}</p><div class="summary-row"><span>Current listing</span><strong>${money(product.price)} / ${escapeHTML(product.unit)}</strong></div><p class="form-hint">The server checks live price, availability and stock again when an authenticated order is submitted.</p><button class="button primary" id="detailAdd" ${catalogReady?'':'disabled'}>Add to basket</button></div>`;$('#detailAdd').onclick=()=>{addToCart(product.id);closePanels();openCart()};openPanel('productModal')});window.addEventListener('amar-auth-change',()=>{if($('#accountModal').classList.contains('open'))void renderAccount()});
initializeLiveCatalog();
